-- mi_tienda_init.sql
DROP DATABASE IF EXISTS mi_tienda;
CREATE DATABASE mi_tienda CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mi_tienda;

CREATE TABLE productos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(100) NOT NULL,
  precio DECIMAL(10,2) NOT NULL,
  stock INT NOT NULL DEFAULT 0,
  categoria VARCHAR(50) NOT NULL
);

INSERT INTO productos (nombre, precio, stock, categoria) VALUES
  ('Portátil HP 15', 649.99, 15, 'Informática'),
  ('Ratón Logitech M185', 19.99, 50, 'Periféricos'),
  ('Teclado mecánico Redragon', 49.99, 30, 'Periféricos'),
  ('Monitor Samsung 24"', 189.99, 20, 'Informática'),
  ('Disco SSD Kingston 480GB', 59.99, 40, 'Almacenamiento');

SELECT * FROM productos;
```

El script se ejecuta sin errores y muestra los 5 productos en la tabla.
